      $('#met-dist-t').textContent = 'Densidad del puntaje latente (escalada por la prevalencia)';
      const lo = -3.5, hi = Math.max(3.5, d + 3.5), xs = []; for (let s = lo; s <= hi + 1e-9; s += 0.05) xs.push(s);
      const ymax = Math.max(...xs.map(s => Math.max(pi * phi(s - d), (1 - pi) * phi(s)))) * 1.1;
      const c = K.chart($('#met-dist'), { width: 380, height: 200, x: [lo, hi], y: [0, ymax], margin: { left: 44, bottom: 38 } });
      c.axes({ xTicks: 6, yTicks: 3, xLabel: 'puntaje latente s', yLabel: 'densidad', xFmt: v => K.fmt(v, 0), yFmt: v => K.fmt(v, 2) });
      const sS = K.clamp(cnt.sStar, lo, hi);
      const area = (fn, from, to, cls) => { const pts = [[from, 0]]; for (let s = from; s <= to + 1e-9; s += 0.05) pts.push([s, fn(s)]); pts.push([to, 0]);
        K.el('path', { d: 'M' + pts.map(p => `${c.X(p[0]).toFixed(1)},${c.Y(p[1]).toFixed(1)}`).join('L') + 'Z', class: cls }, c.g).style.stroke = 'none'; };
      area(s => (1 - pi) * phi(s), sS, hi, 's1 soft'); area(s => pi * phi(s - d), lo, sS, 's5 soft');
      c.path(xs.map(s => [s, (1 - pi) * phi(s)]), 's1 line'); c.path(xs.map(s => [s, pi * phi(s - d)]), 's5 line');
      c.line(sS, 0, sS, ymax, 'muted line');
      c.text(sS, ymax * 0.92, ` θ = ${K.fmt(th, 2)} ⇔ s ≥ ${K.fmt(cnt.sStar, 2)}`, { dx: 4, class: 'strong' });
    }

    // Matriz de confusión.
    $('#met-cm').innerHTML = '<table class="plab-table"><thead><tr><th></th><th>Predicho enfermo</th><th>Predicho sano</th></tr></thead><tbody>' +
      `<tr><td>Real enfermo</td><td class="hl">VP = ${f(cnt.tp)}</td><td>FN = ${f(cnt.fn)}</td></tr>` +
      `<tr><td>Real sano</td><td>FP = ${f(cnt.fp)}</td><td class="hl">VN = ${f(cnt.tn)}</td></tr></tbody></table>` +
      (mode === 'bin' ? '<p class="plab-sub" style="margin:.35rem 0 0">Conteos esperados en una población de 1000 personas.</p>' : '');
    const cost = r * cnt.fn + cnt.fp;
    const stats = [['Exactitud', m.acc], ['Sensibilidad', m.sens], ['Especificidad', m.spec], ['Precisión', m.prec], ['VPN', m.npv], ['F1', m.f1], ['Exact. balanceada', m.bal], ['MCC', m.mcc]];
    $('#met-stats').innerHTML = stats.map(([k, v]) => `<div class="plab-stat"><span>${k}</span><strong>${K.fmt(v, 3)}</strong></div>`).join('') +
      `<div class="plab-stat"><span>Costo (${r}·FN + FP)</span><strong>${K.fmt(cost, dec)}</strong></div>`;

    // Curvas ROC y PR.
    let roc = [], prc = [], auc, base;
    if (mode === 'ej') {
      const all = [...new Set([...POS, ...NEG])].sort((a, b) => b - a), ths = [1.01, ...all];
      ths.forEach(t => { const k = exCounts(t), mm = metrics(k); roc.push([k.fp / 15, k.tp / 5]); if (k.tp + k.fp) prc.push([mm.sens, mm.prec]); });
      auc = 0; POS.forEach(p => NEG.forEach(n => { auc += p > n ? 1 : p === n ? 0.5 : 0; })); auc /= 75; base = 0.25;
    } else {
      for (let t = 0.995; t >= 0.005; t -= 0.005) { const k = binCounts(t, d, pi, N), mm = metrics(k); roc.push([k.fp / ((1 - pi) * N), k.tp / (pi * N)]); if (k.tp + k.fp > 1e-9) prc.push([mm.sens, mm.prec]); }
      roc = [[0, 0], ...roc, [1, 1]]; auc = Phi(d / Math.SQRT2); base = pi;
    }
    const cr = K.chart($('#met-roc'), { width: 300, height: 290, x: [0, 1], y: [0, 1], margin: { left: 44, bottom: 40, right: 10 } });
    cr.axes({ xTicks: 5, yTicks: 5, xLabel: 'FPR (1 − especificidad)', yLabel: 'TPR (sensibilidad)', xFmt: v => K.fmt(v, 1), yFmt: v => K.fmt(v, 1) });
    cr.line(0, 0, 1, 1, 'muted line dash thin');
    cr.path(roc, 's4 line');
    cr.dot(1 - m.spec, m.sens, 6.5, 's2 dot');
    cr.text(0.55, 0.12, `AUC = ${K.fmt(auc, 3)}`, { class: 'strong' });
    const cp = K.chart($('#met-pr'), { width: 300, height: 290, x: [0, 1], y: [0, 1.02], margin: { left: 44, bottom: 40, right: 10 } });
    cp.axes({ xTicks: 5, yTicks: 5, xLabel: 'recall (sensibilidad)', yLabel: 'precisión', xFmt: v => K.fmt(v, 1), yFmt: v => K.fmt(v, 1) });
    cp.line(0, base, 1, base, 'muted line dash thin');
    cp.path(prc, 's4 line');
    if (Number.isFinite(m.prec)) cp.dot(m.sens, m.prec, 6.5, 's2 dot');

    // Retroalimentación.
    const note = $('#met-note'), thOpt = 1 / (1 + r);
    const trivialAcc = mode === 'ej' ? 0.75 : 1 - pi;
    if (Number.isNaN(m.prec)) {
      note.className = 'plab-note bad';
      note.textContent = `Con θ = ${K.fmt(th, 2)} nadie se declara enfermo: la precisión no está definida y la sensibilidad es 0, aunque la exactitud sea ${K.fmt(m.acc, 3)}.`;
    } else if (m.acc <= trivialAcc + 1e-9) {
      note.className = 'plab-note warn';
      note.textContent = `Exactitud ${K.fmt(m.acc, 3)}: no supera la del clasificador trivial que declara sanos a todos (${K.fmt(trivialAcc, 3)}), aunque este detectaría 0 enfermos. Mira la sensibilidad (${K.fmt(m.sens, 3)}) y el MCC (${K.fmt(m.mcc, 3)}).`;
    } else {
      note.className = 'plab-note good';
      note.textContent = `De cada 100 enfermos se detectan ${K.fmt(100 * m.sens, 0)}; de cada 100 alarmas, ${K.fmt(100 * m.prec, 0)} son correctas. ` +
        (mode === 'bin' ? `Con probabilidades calibradas, el umbral de mínimo costo es θ* = 1/(1 + ${r}) = ${K.fmt(thOpt, 3)}; el costo actual es ${K.fmt(cost, 1)} por cada 1000 personas.` :
          `Con costo FN/FP = ${r}, el costo total en estos 20 pacientes es ${cost}.`);
    }
  }
  root.querySelectorAll('input[type=range]').forEach(el => el.addEventListener('input', render));
  sync();
  render();
})();
</script>
