### Elegir el umbral con validación

Supongamos que un enfermo no detectado cuesta diez veces más que una falsa alarma. Elegimos el umbral que minimiza el costo **en validación** y lo aplicamos, sin tocarlo, en prueba:

::: {.cell execution_count=6}
``` {.python .cell-code}
ths = np.linspace(0.01, 0.9, 90)
nombre = "Regresión logística"
costo_va = [10 * ((proba_va[nombre] < t) & (y_va == 1)).sum() + ((proba_va[nombre] >= t) & (y_va == 0)).sum() for t in ths]
t_opt = ths[int(np.argmin(costo_va))]

fig = go.Figure(go.Scatter(x=ths, y=costo_va, line=dict(color="#7c3aed")))
fig.add_vline(x=t_opt, line=dict(color="#ea580c"), annotation_text=f"mínimo en validación: {t_opt:.2f}")
fig.add_vline(x=1 / 11, line=dict(color="gray", dash="dot"))
fig.add_vline(x=0.5, line=dict(color="gray", dash="dash"), annotation_text="0.5", annotation_position="bottom right")
fig.update_layout(xaxis_title="umbral θ", yaxis_title="costo en validación", height=360, margin=dict(l=10, r=10, t=20, b=40))
fig.show()
